mapper.select:
select  from dm_alarm_event

    task_id = #{taskId}

        and source_name = #{sourceName}


        and (
            source_name like '%' || #{keyword} || '%'
            or alarm_msg like '%' || #{keyword} || '%'
            or task_name like '%' || #{keyword} || '%'
            or channel_code like '%' || #{keyword} || '%'
            or trigger_rule like '%' || #{keyword} || '%'
        )


        and alarm_level = #{alarmLevel}


        and alarm_status = #{alarmStatus}


        and alarm_time >= #{startTime}


        and alarm_time <= #{endTime}

    and is_deleted = 0

order by alarm_time desc, id desc
